PRAGMA foreign_keys = ON;
PRAGMA journal_mode = WAL;
PRAGMA busy_timeout = 30000;

BEGIN IMMEDIATE;

CREATE TABLE IF NOT EXISTS leads (
    lead_id TEXT PRIMARY KEY,
    source TEXT NOT NULL,
    external_id TEXT NOT NULL,
    payload_sha256 TEXT NOT NULL,
    covered_lives INTEGER NOT NULL CHECK (covered_lives >= 0),
    score INTEGER NOT NULL CHECK (score BETWEEN 0 AND 100),
    UNIQUE (source, external_id)
);

CREATE TABLE IF NOT EXISTS cases (
    case_id TEXT PRIMARY KEY,
    lead_id TEXT NOT NULL REFERENCES leads(lead_id),
    lane TEXT NOT NULL CHECK (
        lane IN ('advisory', 'commission', 'recovery')
    ),
    period TEXT NOT NULL,
    amount_cents INTEGER NOT NULL CHECK (amount_cents > 0),
    state TEXT NOT NULL DEFAULT 'RECEIVED' CHECK (
        state IN (
            'RECEIVED', 'VERIFIED', 'HELD',
            'EARNED', 'SETTLED', 'REJECTED'
        )
    ),
    UNIQUE (lead_id, lane, period)
);

CREATE TABLE IF NOT EXISTS commands (
    request_key TEXT PRIMARY KEY,
    payload_sha256 TEXT NOT NULL,
    case_id TEXT REFERENCES cases(case_id),
    action TEXT NOT NULL,
    evidence_json TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT (
        strftime('%Y-%m-%dT%H:%M:%fZ', 'now')
    )
);

CREATE TABLE IF NOT EXISTS journal (
    entry_id INTEGER PRIMARY KEY,
    command_key TEXT NOT NULL UNIQUE REFERENCES commands(request_key),
    case_id TEXT REFERENCES cases(case_id),
    kind TEXT NOT NULL CHECK (
        kind IN ('earn', 'receive', 'expense', 'fund')
    ),
    debit TEXT NOT NULL,
    credit TEXT NOT NULL,
    cents INTEGER NOT NULL CHECK (cents > 0),
    CHECK (
        (
            kind = 'earn' AND case_id IS NOT NULL
            AND debit = 'AR' AND credit = 'REVENUE'
        )
        OR (
            kind = 'receive' AND case_id IS NOT NULL
            AND debit = 'CASH' AND credit = 'AR'
        )
        OR (
            kind = 'expense' AND case_id IS NULL
            AND debit = 'EXPENSE' AND credit = 'CASH'
        )
        OR (
            kind = 'fund' AND case_id IS NULL
            AND debit = 'CASH' AND credit = 'EQUITY'
        )
    ),
    UNIQUE (case_id, kind)
);

CREATE TABLE IF NOT EXISTS bank_transactions (
    account_ref TEXT NOT NULL,
    bank_ref TEXT NOT NULL,
    command_key TEXT NOT NULL UNIQUE REFERENCES commands(request_key),
    direction TEXT NOT NULL CHECK (direction IN ('IN', 'OUT')),
    cents INTEGER NOT NULL CHECK (cents > 0),
    PRIMARY KEY (account_ref, bank_ref)
);

CREATE INDEX IF NOT EXISTS cases_state_idx ON cases(state);

CREATE TRIGGER IF NOT EXISTS leads_no_update
BEFORE UPDATE ON leads
BEGIN
    SELECT RAISE(ABORT, 'Lead facts are immutable; use reviewed revisions');
END;

CREATE TRIGGER IF NOT EXISTS leads_no_delete
BEFORE DELETE ON leads
BEGIN
    SELECT RAISE(ABORT, 'Lead evidence cannot be deleted');
END;

CREATE TRIGGER IF NOT EXISTS cases_terms_immutable
BEFORE UPDATE OF case_id, lead_id, lane, period, amount_cents ON cases
BEGIN
    SELECT RAISE(ABORT, 'Case terms require a separately reviewed adjustment');
END;

CREATE TRIGGER IF NOT EXISTS cases_no_delete
BEFORE DELETE ON cases
BEGIN
    SELECT RAISE(ABORT, 'Case history cannot be deleted');
END;

CREATE TRIGGER IF NOT EXISTS commands_no_update
BEFORE UPDATE ON commands
BEGIN
    SELECT RAISE(ABORT, 'Commands are append only');
END;

CREATE TRIGGER IF NOT EXISTS commands_no_delete
BEFORE DELETE ON commands
BEGIN
    SELECT RAISE(ABORT, 'Commands are append only');
END;

CREATE TRIGGER IF NOT EXISTS journal_no_update
BEFORE UPDATE ON journal
BEGIN
    SELECT RAISE(ABORT, 'Journal entries are append only');
END;

CREATE TRIGGER IF NOT EXISTS journal_no_delete
BEFORE DELETE ON journal
BEGIN
    SELECT RAISE(ABORT, 'Journal entries are append only');
END;

CREATE TRIGGER IF NOT EXISTS bank_no_update
BEFORE UPDATE ON bank_transactions
BEGIN
    SELECT RAISE(ABORT, 'Bank evidence is append only');
END;

CREATE TRIGGER IF NOT EXISTS bank_no_delete
BEFORE DELETE ON bank_transactions
BEGIN
    SELECT RAISE(ABORT, 'Bank evidence is append only');
END;

COMMIT;

from __future__ import annotations

import hashlib
import json
import sqlite3
import sys


def apply(db_path, request_key, payload):
    required = {
        "source", "external_id", "covered_lives", "renewal_days",
        "case_id", "lane", "period", "amount_cents", "evidence_ref",
    }
    if set(payload) != required:
        raise ValueError("Supply exactly the documented intake fields")
    if not isinstance(request_key, str) or not request_key.strip():
        raise ValueError("A durable request key is required")
    for name in (
        "source", "external_id", "case_id",
        "lane", "period", "evidence_ref",
    ):
        if not isinstance(payload[name], str) or not payload[name].strip():
            raise ValueError("Text identifiers must be nonempty")
    for name in ("covered_lives", "renewal_days", "amount_cents"):
        if type(payload[name]) is not int:
            raise ValueError("Counts, days, and cents must be integers")
    if payload["covered_lives"] < 0 or payload["amount_cents"] <= 0:
        raise ValueError("Lives must be nonnegative and fees positive")
    if not 0 <= payload["renewal_days"] <= 730:
        raise ValueError("Renewal horizon must be within two years")
    period = payload["period"]
    if (
        len(period) != 7 or period[4] != "-"
        or not period[:4].isdigit() or not period[5:].isdigit()
        or not 1 <= int(period[5:]) <= 12
    ):
        raise ValueError("Period must use a four-digit year and month")
    if payload["lane"] not in {"advisory", "commission", "recovery"}:
        raise ValueError("Use a supported operator revenue lane")

    encoded = json.dumps(payload, sort_keys=True, separators=(",", ":"))
    digest = hashlib.sha256(encoded.encode("utf-8")).hexdigest()
    identity = json.dumps(
        [payload["source"], payload["external_id"]],
        separators=(",", ":"),
    )
    lead_id = hashlib.sha256(identity.encode("utf-8")).hexdigest()
    lead_facts = {
        "source": payload["source"],
        "external_id": payload["external_id"],
        "covered_lives": payload["covered_lives"],
        "renewal_days": payload["renewal_days"],
    }
    lead_digest = hashlib.sha256(
        json.dumps(lead_facts, sort_keys=True).encode("utf-8")
    ).hexdigest()
    score = min(
        100,
        min(payload["covered_lives"], 1000) // 20
        + (50 if 60 <= payload["renewal_days"] <= 180 else 10),
    )

    connection = sqlite3.connect(db_path, timeout=30, isolation_level=None)
    connection.execute("PRAGMA foreign_keys = ON")
    connection.execute("PRAGMA busy_timeout = 30000")
    try:
        connection.execute("BEGIN IMMEDIATE")
        prior = connection.execute(
            "SELECT payload_sha256, action FROM commands WHERE request_key = ?",
            (request_key,),
        ).fetchone()
        if prior:
            if prior != (digest, "intake"):
                raise ValueError("Request key reused with different content")
            connection.commit()
            return "replayed"

        existing = connection.execute(
            "SELECT payload_sha256 FROM leads WHERE lead_id = ?",
            (lead_id,),
        ).fetchone()
        if existing and existing[0] != lead_digest:
            raise ValueError("Changed source facts require a reviewed revision")
        if not existing:
            connection.execute(
                "INSERT INTO leads VALUES (?, ?, ?, ?, ?, ?)",
                (
                    lead_id, payload["source"], payload["external_id"],
                    lead_digest, payload["covered_lives"], score,
                ),
            )

        connection.execute(
            """
            INSERT INTO cases (
                case_id, lead_id, lane, period, amount_cents
            ) VALUES (?, ?, ?, ?, ?)
            """,
            (
                payload["case_id"], lead_id, payload["lane"],
                period, payload["amount_cents"],
            ),
        )
        connection.execute(
            """
            INSERT INTO commands (
                request_key, payload_sha256, case_id, action, evidence_json
            ) VALUES (?, ?, ?, 'intake', ?)
            """,
            (request_key, digest, payload["case_id"], encoded),
        )
        connection.commit()
        return "created"
    finally:
        if connection.in_transaction:
            connection.rollback()
        connection.close()


if __name__ == "__main__":
    with open(sys.argv[3], encoding="utf-8") as handle:
        supplied = json.load(handle)
    print(apply(sys.argv[1], sys.argv[2], supplied))

from __future__ import annotations

import hashlib
import json
import sqlite3
import sys


TRANSITIONS = {
    "verify": (
        "RECEIVED", "VERIFIED",
        ("license_ref", "disclosure_ref", "source_reconciliation_ref"),
    ),
    "hold": (
        "VERIFIED", "HELD",
        ("contract_ref", "acceptance_rule_ref"),
    ),
    "earn": (
        "HELD", "EARNED",
        ("service_completed_ref", "fee_authorized_ref", "release_ref"),
    ),
}


def apply(db_path, request_key, case_id, action, evidence):
    if action not in TRANSITIONS and action != "reject":
        raise ValueError("Unsupported workflow action")
    if not all(
        isinstance(value, str) and value.strip()
        for value in (request_key, case_id)
    ):
        raise ValueError("Request key and case identifier are required")
    if not isinstance(evidence, dict):
        raise ValueError("Evidence must be an object of document references")
    required = (
        ("rejection_reason_ref",)
        if action == "reject"
        else TRANSITIONS[action][2]
    )
    if not all(
        isinstance(evidence.get(name), str) and evidence[name].strip()
        for name in required
    ):
        raise ValueError("Every transition requires its documentary references")

    payload = {"case_id": case_id, "action": action, "evidence": evidence}
    encoded = json.dumps(payload, sort_keys=True, separators=(",", ":"))
    digest = hashlib.sha256(encoded.encode("utf-8")).hexdigest()
    connection = sqlite3.connect(db_path, timeout=30, isolation_level=None)
    connection.execute("PRAGMA foreign_keys = ON")
    connection.execute("PRAGMA busy_timeout = 30000")
    try:
        connection.execute("BEGIN IMMEDIATE")
        prior = connection.execute(
            "SELECT payload_sha256, action FROM commands WHERE request_key = ?",
            (request_key,),
        ).fetchone()
        if prior:
            if prior != (digest, action):
                raise ValueError("Request key reused with different content")
            connection.commit()
            return "replayed"

        case = connection.execute(
            "SELECT state, amount_cents FROM cases WHERE case_id = ?",
            (case_id,),
        ).fetchone()
        if case is None:
            raise ValueError("Create the case before advancing its workflow")
        state, amount = case
        if action == "reject":
            if state not in {"RECEIVED", "VERIFIED", "HELD"}:
                raise ValueError("Posted cases require a reviewed adjustment")
            expected, target = state, "REJECTED"
        else:
            expected, target, unused = TRANSITIONS[action]
            if state != expected:
                raise ValueError("Workflow transition is out of sequence")

        connection.execute(
            """
            INSERT INTO commands (
                request_key, payload_sha256, case_id, action, evidence_json
            ) VALUES (?, ?, ?, ?, ?)
            """,
            (request_key, digest, case_id, action, encoded),
        )
        changed = connection.execute(
            "UPDATE cases SET state = ? WHERE case_id = ? AND state = ?",
            (target, case_id, expected),
        ).rowcount
        if changed != 1:
            raise RuntimeError("State comparison failed; transaction aborted")
        if action == "earn":
            connection.execute(
                """
                INSERT INTO journal (
                    command_key, case_id, kind, debit, credit, cents
                ) VALUES (?, ?, 'earn', 'AR', 'REVENUE', ?)
                """,
                (request_key, case_id, amount),
            )
        connection.commit()
        return target
    finally:
        if connection.in_transaction:
            connection.rollback()
        connection.close()


if __name__ == "__main__":
    with open(sys.argv[5], encoding="utf-8") as handle:
        supplied = json.load(handle)
    print(apply(
        sys.argv[1], sys.argv[2], sys.argv[3], sys.argv[4], supplied
    ))

from __future__ import annotations

import hashlib
import json
import sqlite3
import sys


def apply(db_path, request_key, payload):
    required = {
        "kind", "case_id", "account_ref", "bank_ref",
        "cents", "statement_ref", "document_ref",
    }
    if set(payload) != required:
        raise ValueError("Supply exactly the documented settlement fields")
    if not isinstance(request_key, str) or not request_key.strip():
        raise ValueError("A durable request key is required")
    kind = payload["kind"]
    if kind not in {"receive", "expense", "fund"}:
        raise ValueError("Use receive, expense, or fund")
    if type(payload["cents"]) is not int or payload["cents"] <= 0:
        raise ValueError("Settlement must use positive integer cents")
    for name in ("account_ref", "bank_ref", "statement_ref", "document_ref"):
        if not isinstance(payload[name], str) or not payload[name].strip():
            raise ValueError("Bank and document references must be nonempty")
    if kind == "receive":
        if (
            not isinstance(payload["case_id"], str)
            or not payload["case_id"].strip()
        ):
            raise ValueError("Receipts require an earned case identifier")
    elif payload["case_id"] is not None:
        raise ValueError("Funding and expenses cannot attach to client cases")

    encoded = json.dumps(payload, sort_keys=True, separators=(",", ":"))
    digest = hashlib.sha256(encoded.encode("utf-8")).hexdigest()
    connection = sqlite3.connect(db_path, timeout=30, isolation_level=None)
    connection.execute("PRAGMA foreign_keys = ON")
    connection.execute("PRAGMA busy_timeout = 30000")
    try:
        connection.execute("BEGIN IMMEDIATE")
        prior = connection.execute(
            "SELECT payload_sha256, action FROM commands WHERE request_key = ?",
            (request_key,),
        ).fetchone()
        if prior:
            if prior != (digest, kind):
                raise ValueError("Request key reused with different content")
            connection.commit()
            return "replayed"

        if kind == "receive":
            case = connection.execute(
                "SELECT state, amount_cents FROM cases WHERE case_id = ?",
                (payload["case_id"],),
            ).fetchone()
            if case != ("EARNED", payload["cents"]):
                raise ValueError("Only exact, earned, full receipts are accepted")
            debit, credit, direction = "CASH", "AR", "IN"
        elif kind == "expense":
            debit, credit, direction = "EXPENSE", "CASH", "OUT"
        else:
            debit, credit, direction = "CASH", "EQUITY", "IN"

        connection.execute(
            """
            INSERT INTO commands (
                request_key, payload_sha256, case_id, action, evidence_json
            ) VALUES (?, ?, ?, ?, ?)
            """,
            (request_key, digest, payload["case_id"], kind, encoded),
        )
        connection.execute(
            """
            INSERT INTO bank_transactions (
                account_ref, bank_ref, command_key, direction, cents
            ) VALUES (?, ?, ?, ?, ?)
            """,
            (
                payload["account_ref"], payload["bank_ref"],
                request_key, direction, payload["cents"],
            ),
        )
        connection.execute(
            """
            INSERT INTO journal (
                command_key, case_id, kind, debit, credit, cents
            ) VALUES (?, ?, ?, ?, ?, ?)
            """,
            (
                request_key, payload["case_id"], kind,
                debit, credit, payload["cents"],
            ),
        )
        if kind == "receive":
            changed = connection.execute(
                """
                UPDATE cases SET state = 'SETTLED'
                WHERE case_id = ? AND state = 'EARNED'
                """,
                (payload["case_id"],),
            ).rowcount
            if changed != 1:
                raise RuntimeError("Receipt state comparison failed")
        connection.commit()
        return "posted"
    finally:
        if connection.in_transaction:
            connection.rollback()
        connection.close()


if __name__ == "__main__":
    with open(sys.argv[3], encoding="utf-8") as handle:
        supplied = json.load(handle)
    print(apply(sys.argv[1], sys.argv[2], supplied))
